def read_params(path, *args):
    """Read parameters from file, so that it's readable by write_params.

    Uses INI file format.
    """
    result = {}
    for key, val in args:
        result[key] = {}
    with open(path, 'r') as f:
        for line in f:
            if line[0] == '[' and line[-1] == ']':
                section = line[1:-1]
                continue
            if line.strip() == '':
                continue
            key, val = line.split('=')
            result[section][key] = val
    return result

def read_params_from_commandline(args):
    """Read parameters from command line, so that it's readable by write_params.

    Uses INI file format.
    """
    result = {}
    for arg in args:
        result[arg] = {}
    for key, val in args:
        result[key] = val
    return result


